import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAW: [CaseTemplate] = [officeLaptopRaid, cabDriverRobbery, inspectorShove, employeeIdentityTheft, trafficStopBribe, videoThreatExtortion, pillDiversion, quadWreckDeath, keyboardSabotage, hatchetDispute, pawnShopKilling, exPartnerStabbing, restaurantFireClaim, rentalBatAssault, elderHomeNight, parkingOfficeSafe, barBrokenBottle, dieselDrainage, lotInvestmentFraud]

    static let officeLaptopRaid = SmallCases.make(
        key: "story.officeLaptopRaid",
        category: .property,
        headlines: ["Offices Entered Overnight, Eleven Laptops Gone", "Alarm Log Shows Side Door Forced at 2 A.M."],
        law: "feloniousBE",
        threshold: 6,
        spec: "Broke and entered a building of {V}, an accounting firm, with intent to commit larceny therein, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Eleven laptops worth $13,000 were taken from an accounting firm after a side door was forced at 2 a.m. on {DATE}. A courier's van seen on the street matched a van rented to {D}. Two laptops were sold online from {D}'s account. {DL} says {D.he} bought the laptops from a coworker.",
        state: [E(.digital, 3, "Online Listings", "Two firm laptops listed from {D}'s account."), E(.video, 2, "Street Camera", "A van backs to the side door at 2 a.m.")],
        defense: [E(.statement, 1, "Coworker", "{DL} says a coworker sold {D.him} the laptops.")],
        role: "Firm partner",
        exam: [.direct("Please tell us about your firm and what was in the office.", "\"We're an accounting firm with fourteen employees. Each person has a company laptop, and we also keep a few spares for interns and temporary staff.\""), .direct("What was taken from your firm?", "\"Eleven laptops worth about $13,000. A side door was forced at 2 a.m., and we found the empty desks when we arrived that morning.\""), .direct("How did {D} come into the investigation?", "\"Two of our laptops were listed for sale online from {D}'s account. Our asset tags were visible in the listing photos.\""), .direct("What did the street camera show?", "\"A van backing up to our side door at 2 a.m. A van that matched it had been rented to {D.him}.\""), .direct("What did you find when you arrived that morning?", "\"The side door had been pried open with a flat tool, and the whole equipment closet was empty. Eleven laptops were gone, and the alarm had been disabled.\""), .direct("How did you find out where the laptops went?", "\"A staff member searched for our model online and found two listings. The photos showed our asset tags on the bottom of the machines.\""), .cross("{D} says the laptops were bought from a coworker, doesn't {D.he}?", "\"That is what {D.he} says. {D.He} has not been able to name the coworker or show a receipt.\""), .cross("Many vans look alike on a dark street, don't they?", "\"They do. The rental records are what tie that particular van to {D.him}.\""), .cross("Did anyone see {D} at the firm that night?", "\"No. The camera shows a van, not a face, and nobody saw who was at the door.\""), .cross("Did the street camera show the driver or the van's plate?", "\"Only the side of the van and part of a plate. A deputy traced it to a rental company, and the rental company gave us the renter's name.\""), .cross("Did any of your employees have access to the equipment closet?", "\"Several did. Our office manager and two senior staff had keys, and the closet wasn't locked during the day.\"")],
        defenseRole: "Defendant's coworker",
        defenseExam: [.direct("Did you sell laptops to {D}?", "\"Never. I have never sold {D} a laptop or anything from that firm, and I did not know {D.he} was selling any.\""), .direct("Where were you at 2 a.m. that night?", "\"At home asleep. I did not leave the house, and I was nowhere near that office.\""), .direct("Do you know anything about the van?", "\"Only that deputies asked about it. I never drove it and I never signed for it.\""), .direct("How do you know the defendant?", "\"We work in the same department at a different company. We eat lunch together a few times a month.\""), .direct("Did you ever borrow a van from the defendant?", "\"No. I've never rented one or borrowed one, and I wouldn't know where to take a van at that hour.\""), .direct("What do you know about the defendant's work history before this?", "\"{D.He} has worked at the firm for years and never had a complaint about equipment. I trusted {D.him} with keys and never had a problem.\""), .cross("Did the defendant say you sold {D.him} the laptops?", "\"Yes, that is what deputies said. I do not understand why, because it is not true.\""), .cross("Do you work with {D}?", "\"We know each other from work. We are not close, and we do not socialize.\""), .cross("Can anyone confirm you were at home?", "\"No. I live alone, so nobody can say. I wish I had a better answer.\""), .cross("Can your roommate confirm you were home?", "\"My roommate was out of town that weekend. I don't have anyone who can confirm it.\""), .cross("Why would the defendant say you sold {D.him} the laptops?", "\"I don't know. I've never sold {DF} anything, and I was as surprised as anyone.\"")],
        theory: ("{D} took laptops from an office.", "A purchase from a coworker."),
        allocution: "\"I did it. I'm sorry.\"",
        truths: ("The firm's asset tags were visible in the listing photos.", "The rental agency's log shows a second driver, a coworker, signed for the van that week."),
        defendant: [.direct("Did you break into the accounting firm?", "\"No. I did not break in, and I was never at that building. I do not even know where the side door is.\""), .direct("Where did the laptops come from?", "\"I bought them from a coworker at a good price. I planned to resell them online for a small profit.\""), .direct("Why did you rent a van?", "\"I lent the rented van to someone for a few days. I did not drive it that night.\""), .direct("Tell the jury why you rented a van that week.", "\"I was helping a friend move and needed the van for a day. I'd rented from that company before and I signed the contract at the counter.\""), .direct("Who had the van at the time of the break-in?", "\"A coworker asked to borrow it the night before and I handed over the keys. I didn't ask why.\""), .direct("How did you come to have two of the laptops?", "\"The coworker sold them to me for a low price, saying they were from a company clearing out old stock. I listed two online to resell.\""), .cross("The asset tags were visible in your listing photos. Didn't you notice?", "\"I did not look closely. I took the photos fast, and I did not read the tags.\""), .cross("Who is the coworker who sold them to you?", "\"I can name someone, but it is hard to prove, and I know that is a problem for me.\""), .cross("The van was rented in your name, wasn't it?", "\"Yes, but others had it. A second driver signed for it that week, as I understand it.\""), .cross("The asset tags were visible in the listing photos. Didn't you see them?", "\"I wasn't paying attention to the bottoms of the machines. I took the photos quickly and didn't look closely.\""), .cross("You can't name the coworker with confidence. Isn't that because there was no coworker?", "\"There was one. I'm hesitant because I don't want to accuse someone I'm not sure about, but I know who it was.\"")],
        openings: ("Eleven laptops worth $13,000 were taken from an accounting firm after a side door was forced at 2 a.m. A van seen on camera matches one rented to {D}, and two laptops were listed online from {D}'s account.", "Jurors will hear that {D} bought the laptops from a coworker and never touched that door. A rented van was shared, and a listing proves a sale, not a burglary."),
        closings: ("A forced door, a van backing up at 2 a.m., and two of the firm's laptops for sale from {D}'s account with asset tags visible. These facts lead to one person.", "The camera shows a van, not a face, and the rental records show a second driver that week. {D} bought laptops and sold them. That does not prove {D} broke into anything."),
        timeline: [(-1, "{DL} rents a van."), (0, "2 a.m.: the side door is forced."), (0, "7 a.m.: staff find the laptops gone.")],
        identified: "Online listings.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let cabDriverRobbery = SmallCases.make(
        key: "story.cabDriverRobbery",
        category: .robbery,
        headlines: ["Taxi Driver Held Up With Pistol, $310 Taken", "Dispatch Log Shows Fare Called From Payphone Area"],
        law: "dangerousRobbery",
        threshold: 8,
        spec: "Took $310 from the person and presence of {V}, a taxi driver, by endangering {V.his} life with a firearm, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A passenger put a pistol to {V}'s neck on {DATE} and took $310 from a taxi driver on a rural road. The fare was called in from a number tied to {D}. A pistol was found in {D}'s apartment. {DL} says {D.he} was at work.",
        state: [E(.digital, 3, "Dispatch Call", "The fare was ordered from {D}'s phone."), E(.physical, 3, "Pistol", "A pistol matching the victim's description.", .search)],
        defense: [E(.statement, 1, "At Work", "{DL} says {D.he} was at work.")],
        role: "Taxi driver",
        exam: [.direct("Tell the jury how long you've driven a taxi and how a fare reaches you.", "\"Eleven years. Most fares come through the dispatch app, and I get a pickup address and a phone number for the passenger.\""), .direct("What happened on the rural road that night?", "\"A fare I'd picked up pulled a pistol and put it to my neck. I was told to hand over my cash, and I gave up $310.\""), .direct("How did you get that fare?", "\"It came through dispatch. The call was ordered from a number tied to {D}'s phone. I picked up the passenger and drove out toward the country.\""), .direct("What can you tell the jury about the pistol?", "\"It was a dark handgun, held right against my neck. Deputies later found a pistol in {D.his} apartment that matches what I described.\""), .direct("What happened after you picked up this fare?", "\"The passenger sat behind me, gave a destination on a rural road, and said nothing else. About ten miles out, the passenger put a pistol against my neck and told me to pull over.\""), .direct("What did the passenger take?", "\"$310 from my cash box and my phone. The passenger got out, walked into the trees, and I heard a car start somewhere out of view.\""), .cross("Could you see the passenger's face clearly?", "\"Not clearly. It was dark, and the passenger kept a hat low. I focused on the pistol, not the face.\""), .cross("Did you identify {DL} in a lineup?", "\"I wasn't able to make a positive identification of {DL}. I can describe the pistol and what happened, but I can't swear to a face.\""), .cross("Did the passenger say anything that identified anyone?", "\"No. The passenger said very little, only to hand over the money. I never got a name.\""), .cross("Did you see the passenger's face?", "\"Only in the mirror, for a second or two, in the dark. I couldn't describe more than the build and a dark cap.\""), .cross("What did you tell deputies about the pistol?", "\"That it was dark and small, maybe a revolver. I'd never seen it before and I couldn't tell the make.\"")],
        defenseRole: "Defendant's supervisor",
        defenseExam: [.direct("Does {DL} work for you?", "\"Yes, {D} works for me. I keep the schedule and the time records, and I know when {D.he} clocked in and out.\""), .direct("When did {DL} clock out that night?", "\"At 8 p.m. The time record shows it. That's the end of the shift, and {D.he} left on time.\""), .direct("Was {DL} reliable?", "\"Yes. {D.He} came in on time, did the work, and never caused trouble. I've never had a complaint.\""), .direct("How are you connected to {D}?", "\"I'm {DF}'s supervisor at the distribution center. {DF} has worked on my shift for two years.\""), .direct("What time did the defendant clock out that night?", "\"8 p.m., which is what the time record shows. I remember because we had a late truck and everyone was glad to go.\""), .direct("What kind of employee is the defendant?", "\"Reliable, quiet, and never in trouble. {D.He} has never missed a shift without calling.\""), .cross("Could {DL} have been elsewhere after 8?", "\"After 8, yes. I don't track where employees go after they leave. I only know when {D.he} clocked out.\""), .cross("Do you know where {DL} went after clocking out?", "\"No. I don't follow my employees home. I only know the shift ended at 8.\""), .cross("Do you know about the cab call?", "\"Only what I've been told. I don't know who made it. I can't speak to that at all.\""), .cross("Did the defendant ever mention the phone number or a taxi?", "\"No. We never talked about taxis, and {D.he} has never said anything about a robbery.\""), .cross("Could the defendant have left work early that night without your seeing?", "\"It is possible. I was in the back office much of the shift. I saw the clock-out but not where {D.he} went after.\""), .cross("Did {D} tell you anything about a pistol at home?", "\"No. {D.He} never mentioned owning one, and I never saw any weapon at work.\"")],
        theory: ("{D} robbed a driver.", "A worker at work."),
        allocution: "\"I'm sorry for the fear.\"",
        truths: ("The pistol had the driver's blood type on the grip.", "The fare call came from a number {DL} had given up two weeks earlier."),
        defendant: [.direct("Did you order that taxi?", "\"No. I didn't call for a cab that night. I was at work, and I have no idea who used my number.\""), .direct("Where were you when the robbery happened?", "\"At work. My supervisor can tell you when I clocked out. I did not leave my shift to rob anyone.\""), .direct("Why was a pistol in your apartment?", "\"I keep it at home. It's mine, and I never took it out that night. Lots of people own a pistol like that.\""), .direct("Tell the jury where you work and when you got off that night.", "\"At a distribution center across town. My shift ends at eight, and I clocked out and drove home that night.\""), .direct("How do you explain the phone number on the dispatch call?", "\"It was my old number. I gave it up two weeks before, and I don't know who had it.\""), .direct("What happened to the phone number on the dispatch call after you gave it up?", "\"I gave that number up two weeks earlier. I assume someone else was assigned it, and I did not know anyone was using it.\""), .cross("The fare was ordered from your phone, wasn't it?", "\"That's what they say. I can't explain it. Someone else may have had my phone or my number.\""), .cross("You clocked out at 8 p.m., didn't you?", "\"Yes, and I was home after that. I don't have anyone who can say exactly where I was after work.\""), .cross("The pistol matches the driver's description, doesn't it?", "\"It's a common kind of pistol. A lot of people have one like it. That doesn't make it the one used.\""), .cross("A pistol was found in your apartment. Why do you have one?", "\"I bought it for protection years ago and I keep it in a drawer. It's registered, and I've never used it on anyone.\""), .cross("You had no alibi for 9:40. Isn't that when the robbery happened?", "\"I was home alone. I don't have a witness, but I wasn't on that road.\"")],
        openings: ("A passenger put a pistol to a taxi driver's neck on a rural road and took $310. The fare was ordered from a number tied to {D}'s phone, and a matching pistol was in {D}'s apartment. The State will show the call record and the pistol.", "Jurors will also see a person at work until 8, a phone number that anyone could have used, and a driver who could not identify a face. A number and a pistol are not a robber."),
        closings: ("A fare ordered from {D}'s phone, a pistol at the driver's neck, and a matching pistol in {D}'s apartment. The pieces fit together, and the driver lived through it.", "The driver never saw a face. A phone number can be used by anyone, and a common pistol proves nothing. The State has not proved {D} was in that cab."),
        timeline: [(0, "9:10 p.m.: the fare is ordered."), (0, "9:40 p.m.: the robbery."), (0, "10 p.m.: the driver calls deputies.")],
        identified: "A dispatch call and a pistol.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction)

    static let inspectorShove = SmallCases.make(
        key: "story.inspectorShove",
        category: .violent,
        headlines: ["Code Inspector Shoved During Property Visit", "Body Camera Records Push at the Door"],
        law: "assaultGovOfficial",
        threshold: 6,
        spec: "Assaulted {V}, a county code inspector, while the official was discharging official duties, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A county code inspector arrived at {D}'s property on {DATE} to cite a junk pile. {D} shoved {V} off the porch. The inspector's body camera recorded it. {DL} says {V} stepped onto the porch uninvited.",
        state: [E(.video, 3, "Body Camera", "{D} shoves {V} off the porch."), E(.document, 2, "Inspection Order", "A written order to inspect the property.")],
        defense: [E(.statement, 1, "Uninvited", "{DL} says {V} entered the porch uninvited.")],
        role: "Code inspector",
        exam: [.direct("Tell the jury about your job and what you were doing that day.", "\"I'm a county code inspector. I respond to complaints about junk, unsafe structures, and overgrown lots, and I had a written order to inspect {D}'s property.\""), .direct("Why did you go to {DL}'s property on {DATE}?", "\"I'm a county code inspector, and I had a written inspection order to cite a junk pile on the property. I arrived to look at it.\""), .direct("What happened on the porch?", "\"I stepped toward the porch to speak with {D.him}, and {D.he} shoved me off it. I fell and was hurt. My body camera recorded the whole thing.\""), .direct("What does your body camera show?", "\"{D.He} shoves me off the porch with both hands. You can see the shove, my fall, and the porch steps. It's clear.\""), .direct("How did you approach the property?", "\"I parked on the street, walked up the driveway, and called out that I was with the county. I stepped onto the bottom porch step to knock.\""), .direct("What did {D} do when you reached the porch?", "\"The door opened and {D.he} came out fast, put both hands on my chest, and shoved me off the porch. I fell about three feet onto the ground.\""), .cross("{DL} says you stepped onto the porch uninvited, doesn't {D.he}?", "\"I walked up to the porch to announce myself. I was there on official business under an order. I didn't force my way in.\""), .cross("Did you knock or announce yourself first?", "\"I called out as I came up the walk. I may have reached the porch as I was speaking. It was a few seconds, not a long process.\""), .cross("Were you seriously hurt?", "\"I was hurt, but not catastrophically. A fall off a porch is not a minor thing, and I was sore for some time.\""), .cross("Did you identify yourself with a badge or an ID before you stepped onto the porch?", "\"I wore a vest with the county seal and had my ID on a lanyard. I called out my name and title before I got to the step.\""), .cross("Were you hurt?", "\"A scraped elbow and a bruised hip. I did not need medical care, but I filed an incident report.\"")],
        theory: ("{D} shoved an official.", "A defense of property."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had warned the inspector by letter.", "The inspector arrived in an unmarked car without announcing the visit, per a neighbor."),
        defendant: [.direct("Why did you push the inspector?", "\"I didn't know who it was. Someone I hadn't invited stepped onto my porch, and I reacted. I pushed to keep the person off.\""), .direct("Did you intend to hurt the inspector?", "\"No. I only wanted the person off my porch. I didn't realize the inspector would fall off the porch and be hurt.\""), .direct("How do you feel about the junk pile?", "\"I know it's an issue. I'd been planning to clean it up. I wasn't trying to fight anyone about it.\""), .direct("Describe what you were doing at home that morning.", "\"I was in the kitchen having coffee when I heard a noise on the porch. I thought someone was trying to get in.\""), .direct("What did you see when you opened the door?", "\"A person in a vest standing on my porch step. I didn't read the vest, and I just wanted whoever it was off my porch.\""), .direct("What did you do?", "\"I shoved the person away, and then I saw the county patch and a clipboard and realized who it was. I tried to help the inspector up.\""), .cross("The inspector was there on official business, wasn't it?", "\"I know that now. At that moment, I just saw someone coming up on my porch, and I reacted.\""), .cross("The video shows you pushing with both hands, doesn't it?", "\"Yes. I'm not denying it. I regret that. I wish I had just talked to the inspector.\""), .cross("You knew about the inspection, didn't you?", "\"I knew an inspection was possible. I didn't know it would happen that day. I should have been calmer.\""), .cross("You had a letter from the county about the junk pile. Weren't you expecting an inspector?", "\"I'd gotten a letter weeks earlier, and I'd even written back asking for more time. I didn't know the visit was that day.\""), .cross("The body camera shows you shoving with both hands. Isn't that more than a reflex?", "\"It was fast, but yes, it was both hands. I'm not denying it and I'm so sorry.\"")],
        openings: ("A county code inspector arrived at {D}'s property to cite a junk pile. {D} shoved the inspector off the porch, and the inspector's body camera recorded it. The State will show the video and the inspection order.", "The defense evidence includes a homeowner surprised by someone on the porch, a push that was a reflex, and no intent to injure. {D} was protecting a doorstep, not attacking a public official."),
        closings: ("Two hands, a shove, and a fall off a porch, all on the inspector's body camera. {D} knew who stood there and pushed anyway.", "A homeowner startled on the porch pushed once and regretted it. The State has not proved {D} meant to hurt an official rather than keep a stranger away."),
        timeline: [(0, "10 a.m.: the inspector knocks."), (0, "10:03 a.m.: the shove."), (0, "10:30 a.m.: deputies arrive.")],
        identified: "Body camera.",
        aggravating: ["The victim was a law enforcement officer performing official duties"],
        mood: .indifferent)

    static let employeeIdentityTheft = SmallCases.make(
        key: "story.employeeIdentityTheft",
        category: .cyber,
        headlines: ["Employee Opened Credit in Coworker's Name Using Payroll File", "HR Finds Application Matches Personnel Record"],
        law: "identityTheft",
        threshold: 6,
        spec: "Knowingly obtained and used the identifying information of {V} to obtain credit, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} learned on {DATE} that a store card in {V.his} name carried $4,300 in charges. The application used {V}'s Social Security number from a personnel file. {D}, who worked in the payroll office, had accessed the file the week before. {DL} says a vendor mishandled the file.",
        state: [E(.digital, 3, "Access Log", "{D} opened {V}'s personnel file four days before the application."), E(.document, 3, "Application", "A store card application using {V}'s identifying information.")],
        defense: [E(.statement, 1, "Vendor", "{DL} says a vendor mishandled the file.")],
        role: "Coworker",
        exam: [.direct("Tell the jury about your job and your relationship with {D}.", "\"I work in the finance department at the same company. {D} works in the payroll office on another floor, and we've talked in the elevator a handful of times.\""), .direct("How did you learn about the store card?", "\"A letter came saying a store card in my name carried $4,300 in charges. I had never applied for one, so I reported it at once.\""), .direct("What did the application contain?", "\"My Social Security number and other identifying information that could only come from my personnel file. It was a full application in my name.\""), .direct("How is {DL} connected to your file?", "\"{D.He} works in the payroll office and opened my personnel file four days before the application was submitted. The access log shows it.\""), .direct("How did you find out about the card?", "\"A letter came saying a new store card in my name had a balance of $4,300. I'd never applied for it, so I called the store and the number on the letter.\""), .direct("What did the store say about the application?", "\"It had been submitted online with my name, my Social Security number, and my address. The card shipped to an address that wasn't mine.\""), .cross("Did you see {DL} open your file?", "\"No. I only know it from the access log. I wasn't there, and I can't say what {D.he} did on the screen.\""), .cross("Do other people have access to personnel files?", "\"Several people do, including payroll and HR staff. And I understand there are outside vendors who handle some data.\""), .cross("Did {DL} ever say anything to you about your information?", "\"No. {D.He} never mentioned it and never asked me about anything personal. We barely spoke except about work.\""), .cross("How many people at the company can see your personnel file?", "\"The payroll staff, HR, and my supervisor. That's at least six people, and I've never kept track of who looks.\""), .cross("Do you have any reason to think the defendant wanted to harm you?", "\"No. We've never had a disagreement and I have no reason to think {D.he} would do this.\"")],
        theory: ("{D} used a coworker's information to open credit.", "A vendor's breach."),
        allocution: "\"I'm sorry.\"",
        truths: ("The card shipped to {DL}'s cousin's address.", "The payroll vendor's audit showed a breach that exposed the whole file the week before."),
        defendant: [.direct("Why did you open {V}'s personnel file?", "\"As part of my job in payroll. I open files all the time for routine reasons. I didn't take any information for personal use.\""), .direct("Did you apply for that store card?", "\"No. I never applied for a card in {V}'s name. I would never do that to a coworker.\""), .direct("How do you explain the information on the application?", "\"A vendor mishandled the file. We use outside vendors for payroll data, and any one of them could have exposed it.\""), .direct("Tell the jury about your role in payroll.", "\"I handle raises, bonuses, and tax forms for about three hundred employees. I open files every day, and the system logs each one.\""), .direct("Why did you open {V}'s file that week?", "\"{V} had submitted a change to a tax form. I opened the file, made the change, and closed it.\""), .direct("How do you think the information got out?", "\"A payroll vendor had a breach the week before. The vendor told us that files from several companies may have been exposed.\""), .cross("The log shows you opened the file four days before the application, doesn't it?", "\"Yes. I did my job. I open many files. It's not unusual for me to access one, and I don't remember each one.\""), .cross("Only a few people could open that file at work, right?", "\"A few, yes. But the vendors and others had copies. I can't say who else saw it.\""), .cross("You had the Social Security number in front of you, didn't you?", "\"I could see it, like anyone with payroll access. That's the job. It doesn't mean I used it.\""), .cross("The card went to an address that belongs to your cousin. How do you explain that?", "\"I don't know. I have a cousin who lives in that area, but I never gave anyone that address for a card.\""), .cross("Opening the file four days before the application is quite a coincidence, isn't it?", "\"It's a coincidence in time, but I open dozens of files each week, and it just happened to be one of them.\"")],
        openings: ("{V} learned that a store card in {V.his} name carried $4,300 in charges. The application used {V}'s Social Security number from a personnel file, and {D}, who works in payroll, opened that file four days earlier. The State will show the access log and the application.", "The defense will point you to a payroll worker who opens files every day as part of the job, a payroll vendor that also handled the file, and no evidence {D} ever applied for a card."),
        closings: ("Four days after {D} opened the file, an application arrived using {V}'s information. The access log and the application tell the same story.", "Opening a file is part of {D}'s job, and others handled that data. The State has an access log and a hunch, not proof that {D} applied for the card."),
        timeline: [(-4, "{DL} opens {V}'s file."), (0, "The card arrives."), (7, "{V} sees the statement.")],
        identified: "An access log.",
        mood: .wantsConviction)

    static let trafficStopBribe = SmallCases.make(
        key: "story.trafficStopBribe",
        category: .whiteCollar,
        headlines: ["Driver Offers Deputy $200 to Tear Up Citation", "Body Camera Records the Offer"],
        law: "bribery",
        threshold: 6,
        spec: "Offered a thing of value to a public official, a deputy, to influence an official act, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "During a traffic stop on {DATE}, {D} slid $200 under a driver's license and said, 'Let's forget this.' The deputy's body camera recorded the offer. {DL} says it was a joke. The offer came about five minutes into a 10 a.m. stop, and the $200 was in twenties. The body camera shows the bills and the words, and the cash was returned.",
        state: [E(.video, 3, "Body Camera", "{D}: 'Let's forget this,' with $200 under the license."), E(.physical, 2, "Bills", "$200 in twenties.", .search)],
        defense: [E(.statement, 1, "Joke", "{DL} says it was a joke.")],
        role: "Sheriff's deputy",
        exam: [.direct("Tell the jury how the traffic stop began.", "\"I saw a car go through a stop sign at about 9:55 and turned on my lights. The driver pulled over right away and handed me a license and registration.\""), .direct("What happened at that traffic stop?", "\"About five minutes into a 10 a.m. stop, {D} slid $200 under {D.his} driver's license and handed it to me.\""), .direct("What did {D} say?", "\"{D.He} said, 'Let's forget this.' My body camera recorded the words and the bills clearly.\""), .direct("What happened to the cash?", "\"I recovered $200 in twenties. It was returned to {D.him} after it was documented.\""), .direct("What exactly did the defendant do with the money?", "\"{DL} slid two twenty-dollar bills, five of them in all, under the license and said, 'Let's forget this.' The bills were folded in half and the license was on top.\""), .direct("What did you do?", "\"I said I couldn't accept the money, set it on the hood, and told {DL} to step out of the car. I called for a second unit and told {DL} {D.he} was under arrest.\""), .cross("{D} says it was a joke, doesn't {D.he}?", "\"That is what {D.he} says. I did not find it funny, and I did not take it as a joke.\""), .cross("Had you told the defendant anything about paying a citation?", "\"I may have mentioned how the citation could be handled. I do not remember the exact words.\""), .cross("Did the defendant seem to be joking on the video?", "\"I cannot say what {D.he} felt. The tone on the video is calm and quiet.\""), .cross("Did {D} say anything about a ticket or a fine before offering the money?", "\"I'd said the ticket could be paid in advance. {D.He} didn't say anything about a ticket after that, only the line about forgetting it.\""), .cross("Was the defendant calm or nervous during the stop?", "\"{D.He} seemed nervous and laughed once. I couldn't tell if it was a joke or fear.\"")],
        theory: ("{D} tried to bribe a deputy.", "A joke."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had taken out cash at an ATM minutes earlier.", "The deputy had mentioned that the citation could be paid on the spot, and {DL} had just withdrawn cash."),
        defendant: [.direct("Did you try to bribe the deputy?", "\"No. I was making a joke. I said 'Let's forget this' with a smile, and I did not mean it seriously.\""), .direct("Why was there cash under your license?", "\"I had just taken money out for gas. It was in my hand, and I put it with my license when I pulled it out.\""), .direct("Did you intend to pay the deputy to skip the citation?", "\"No. I did not intend that at all. I would not have done that if I had thought about it.\""), .direct("Tell us what happened at the traffic stop.", "\"I'd been pulled over for a stop sign. The deputy mentioned I could pay the citation on the spot, and I'd just pulled out cash for gas.\""), .direct("What did you mean by 'Let's forget this'?", "\"It was a nervous joke. I meant that I wanted to forget the whole embarrassing stop, and I put the cash on the license without thinking.\""), .direct("What did you do when the deputy refused it?", "\"I said I was only joking and apologized. I didn't think it was a serious offense, and I was shocked when I was arrested.\""), .cross("You had just withdrawn cash at an ATM minutes before, didn't you?", "\"Yes, for gas. I was going to fill up after I left the stop.\""), .cross("The deputy had mentioned the citation could be paid on the spot, hadn't they?", "\"Maybe, and I misunderstood. I thought I was supposed to pay, and I do not know the process.\""), .cross("Placing $200 under a license is not a joke. Isn't it exactly how a bribe looks?", "\"I understand that now. In the moment I wasn't thinking about how it looked.\""), .cross("You'd withdrawn the cash just before the stop. Why not wait for the citation?", "\"I'd taken it out for gas. I didn't plan to use it for anything else.\""), .cross("The deputy said the citation could be paid on the spot, didn't the deputy?", "\"Yes. When the deputy said that, I put the cash under my license, thinking that was how it worked. I said let's forget this meaning forget the paperwork.\""), .cross("You offered $200 in twenties, didn't you?", "\"Yes. I had just taken it from the ATM, and I wanted to settle it quickly. I did not mean it as a bribe, but I see how it looked.\"")],
        openings: ("During a traffic stop, {D} slid $200 under a driver's license and told the deputy, 'Let's forget this.' The body camera recorded the words, the bills, and the offer.", "The defense witnesses will explain that {D} had just taken cash out for gas and made a nervous joke. It was never an offer to buy a way out of a ticket."),
        closings: ("Two hundred dollars in twenties under a driver's license and the words 'Let's forget this.' The camera shows exactly what happened, and the deputy was offered a bribe.", "A bad joke at a traffic stop, cash for gas, and a deputy who had just talked about paying on the spot. The State must prove {D} intended to corrupt, and a joke is not that."),
        timeline: [(0, "10 a.m.: the stop."), (0, "10:05 a.m.: the offer."), (0, "10:20 a.m.: the arrest.")],
        identified: "Body camera.",
        mood: .indifferent)

    static let videoThreatExtortion = SmallCases.make(
        key: "story.videoThreatExtortion",
        category: .whiteCollar,
        headlines: ["Contractor Threatens to Post Video Unless Homeowner Pays $5,000", "Texts Demand Payment by Friday"],
        law: "extortion",
        threshold: 7,
        spec: "Threatened {V} with the release of a video to obtain $5,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After a dispute over a bill, {D}, a contractor, texted {V} on {DATE} that a video of {V} in a private moment would be posted unless {V} paid $5,000. {DL} says the text was a bad-tempered bargaining position. The text arrived at noon with a Friday deadline, which passed without the video being posted.",
        state: [E(.digital, 3, "Texts", "'$5,000 by Friday or the video goes up.'"), E(.digital, 2, "Video", "A video of {V} on {D}'s phone.")],
        defense: [E(.statement, 1, "Bargaining", "{DL} says it was a bargaining position.")],
        role: "Homeowner",
        exam: [.direct("Tell the jury about the work {D} did for you.", "\"{D} is a contractor who renovated my kitchen and bathroom. We agreed on a price of $14,000, and the work took about three months.\""), .direct("What did the text from the defendant say?", "\"At noon it read, '$5,000 by Friday or the video goes up.' It came with a deadline and instructions for paying.\""), .direct("What was the background to the text?", "\"We had a dispute over a bill. {DL}, the contractor, believed I owed more than I thought I owed.\""), .direct("What was the video?", "\"A video of me in a private moment. It was on {D.his} phone, and I did not know it existed.\""), .direct("What was the dispute about?", "\"{D.He} billed $2,100 more than we'd agreed. I said the change orders weren't in writing and offered to pay half.\""), .direct("What was in the video, and how did the defendant come to have it?", "\"A clip from a job-site camera that caught me in a private moment in the house. {D.He} had the footage on a phone and told me about it in a text.\""), .cross("{D} says this was bargaining over the bill, doesn't {D.he}?", "\"That is how {D.he} describes it. To me it was a threat, and I felt it as one.\""), .cross("The video was never posted, was it?", "\"No. The Friday deadline passed and nothing was posted, but I was frightened the whole week.\""), .cross("How much did you owe on the bill?", "\"The disputed bill was about $2,100. {D.He} asked for $5,000, which is far more than that.\""), .cross("Did the defendant ever say the video would be posted publicly?", "\"The text said 'the video goes up' if I didn't pay by Friday. It didn't say where, but I understood it as the internet.\""), .cross("How did you feel when you read it?", "\"Frightened and humiliated. I talked to my family, and then I called the sheriff's office.\"")],
        theory: ("{D} tried to extort payment.", "A heated negotiation."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} had set a deadline and a payment account.", "The video was a job-site time-lapse that caught {V} by accident, and {DL} offered to delete it once the bill was paid."),
        defendant: [.direct("Did you threaten to post a video of {V}?", "\"I bargained. I was angry about the bill, and I wrote a text I should not have written.\""), .direct("What was the video?", "\"It was a job-site time-lapse that caught {V.him} by accident. I did not mean it as anything private.\""), .direct("Did you ever post the video?", "\"Never. I did not post it, and I would have deleted it once the bill was paid.\""), .direct("Tell us about the dispute over the bill.", "\"I'd done extra work the owner asked for, like a second set of cabinets, and billed it. The owner refused to pay and said none of it had been agreed to.\""), .direct("Why did you send the text?", "\"I was angry and I wanted to be paid. I'd been stiffed before, and I used the video as leverage, which was a stupid thing to do.\""), .direct("What did you do with the video afterward?", "\"I never posted it. I deleted it from my phone the day the deputy called, and I told the deputy I was sorry.\""), .cross("You set a Friday deadline and a payment account, didn't you?", "\"I did, out of habit. I set deadlines on bills, and I should not have used those words.\""), .cross("$5,000 for a $2,100 bill. How is that bargaining?", "\"It included interest and my time. I know it was too much, and I was angry.\""), .cross("You wrote 'or the video goes up.' What did that mean?", "\"It was a heated way to say I would pursue the bill. I did not mean to publish anything private.\""), .cross("The text set a Friday deadline and said 'the video goes up.' That's a threat, isn't it?", "\"It reads as one. I wrote it in anger and never meant to carry it out.\""), .cross("The video showed {V} in a private moment, didn't it?", "\"It caught {V} by accident on a job-site time-lapse. I know it was private, and I should never have used it as leverage in a billing dispute.\""), .cross("You offered to delete the video only after the bill was paid, didn't you?", "\"Yes. That was the condition I set, and I now see that tying a deletion to payment turned a bill into a threat.\"")],
        openings: ("After a dispute over a bill, {D}, a contractor, texted {V} that a video of {V} in a private moment would go up unless {V} paid $5,000 by Friday. The video was on {D}'s phone.", "Jurors will also see a bad-tempered text during a billing dispute. The video was a job-site time-lapse, it was never posted, and {D} offered to delete it."),
        closings: ("Five thousand dollars by Friday or the video goes up. That is a demand backed by a threat, and the video was on {D}'s phone.", "An angry text in the middle of a bill dispute, a deadline set from habit, and a video that was never posted. That is a heated bargaining position, not extortion."),
        timeline: [(-5, "The billing dispute."), (0, "Noon: the text."), (5, "The Friday deadline passes.")],
        identified: "Texts and a video.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let pillDiversion = SmallCases.make(
        key: "story.pillDiversion",
        category: .drugs,
        headlines: ["Pharmacy Technician Pockets Oxycodone From Inventory", "Audit Finds 120 Pills Unaccounted For"],
        law: "possSchedII",
        spec: "Possessed a Schedule II controlled substance, oxycodone, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "An audit on {DATE} found 120 oxycodone tablets unaccounted for at a pharmacy. A camera showed {D}, a technician, putting a bottle into a coat pocket. A search of {D}'s locker found 36 tablets. {DL} says {D.he} was moving the bottle to a safe.",
        state: [E(.video, 3, "Pharmacy Camera", "{D} puts a bottle into a coat pocket."), E(.physical, 3, "Locker Tablets", "36 oxycodone tablets in {D}'s locker.", .search)],
        defense: [E(.statement, 1, "Moving to Safe", "{DL} says {D.he} was moving it to the safe.")],
        role: "Pharmacist",
        exam: [.direct("Please tell us about your role and how the audit works.", "\"I'm the pharmacist-in-charge. Every month we count controlled substances against the dispensing record, and the audit found 120 oxycodone tablets unaccounted for.\""), .direct("What did your audit find?", "\"120 oxycodone tablets were unaccounted for. We ran the audit because the counts had not matched for a while.\""), .direct("What did the search find?", "\"Thirty-six oxycodone tablets in {D}'s locker. They were in a bag, and they matched what had gone missing.\""), .direct("What does the pharmacy camera show about {D}?", "\"At about three in the afternoon, {DL} takes a bottle from the cabinet, looks around, and puts it in a coat pocket. {DL} then walks toward the staff area.\""), .direct("What did the locker search turn up?", "\"Thirty-six oxycodone tablets in a pill bottle, with a label from the pharmacy that matched the missing bottle's lot number.\""), .direct("How did you narrow down who had been in the pharmacy cabinet?", "\"I pulled the badge log and the camera. A second technician's badge opened the cabinet in the same minute, so I could not rule out that person either.\""), .cross("{D} says {D.he} was moving the bottle to the safe, doesn't {D.he}?", "\"Yes. But the safe is in the other direction from where {D.he} walked, and a coat pocket is not how we move controlled substances.\""), .cross("Several people had access to the controlled-substance cabinet, didn't they?", "\"Yes, a few staff could open it. The log shows who opened it and when.\""), .cross("Did {D} deny having the tablets in the locker?", "\"{D.He} said the locker tablets were not {D.his}. I cannot say how they got there.\""), .cross("Who has access to the controlled-substance cabinet?", "\"Me, two other pharmacists, and four technicians. The cabinet is opened by badge, and the system logs each use.\""), .cross("Did the log show who opened the cabinet at three o'clock?", "\"A second technician's badge opened it the same minute. I can't tell who actually took the bottle out.\"")],
        theory: ("{D} diverted pills.", "A move to a safe."),
        allocution: "\"I'm sorry.\"",
        truths: ("The locker held a lab label for the missing bottle.", "A second technician's badge opened the controlled-substance cabinet the same minute."),
        defendant: [.direct("Did you take pills from the pharmacy?", "\"No. I did not take any pills. I would never put my license at risk like that.\""), .direct("What about the tablets in your locker?", "\"They were not mine. I have no idea how tablets ended up in my locker. Lockers can be opened by others.\""), .direct("Please describe your job as a technician.", "\"I fill prescriptions, restock, and help count. I've worked there for a year and I have a clean record.\""), .direct("Why did you put the bottle in your pocket?", "\"My hands were full of other bottles and I was moving it to the safe. I put it in my pocket to free up a hand.\""), .direct("What about the pills in your locker?", "\"They weren't mine. I don't know how they got there, and my locker isn't locked during shifts.\""), .direct("What did you do with the bottle once you reached the other end of the pharmacy?", "\"I handed it to the pharmacist-in-charge to log. I did not keep it, and I do not know why a bottle with that label ended up in a locker.\""), .cross("The safe is in the opposite direction. Why walk away from it?", "\"I may have set it down on the way. I do not remember every step, and it was a busy day.\""), .cross("A lab label for the missing bottle was in your locker, wasn't it?", "\"Someone must have left it there. I never put that label in my locker.\""), .cross("You are the one seen on camera with the bottle, aren't you?", "\"Yes, but that does not mean I stole it. I was doing my job.\""), .cross("The safe is in the other direction. Why walk away from it?", "\"I may have gone to put something else away first. I don't remember every step.\""), .cross("You were the only person on camera putting a bottle in a pocket, weren't you?", "\"Yes, because I was moving it toward the safe. I put it in my coat to keep my hands free for the door, and I know how that looked.\"")],
        openings: ("An audit found 120 oxycodone tablets missing from a pharmacy. A camera shows {D}, a technician, putting a bottle into a coat pocket, and a search of {D}'s locker turned up 36 tablets.", "The defense case is that {D} was moving the bottle while carrying other items and that others could reach that locker and the cabinet."),
        closings: ("A bottle into a coat pocket on camera, 36 tablets in {D}'s locker, and 120 tablets missing. A pocket is not a safe, and a locker is not a pharmacy shelf.", "The State shows a pocket and a locker, but cannot say who else had access to either. A second technician opened the cabinet that same minute. Doubt remains."),
        timeline: [(-30, "{DL} starts at the pharmacy."), (0, "3 p.m.: {DL} pockets a bottle."), (1, "The audit finds the gap.")],
        identified: "A pharmacy camera.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction)

    static let quadWreckDeath = SmallCases.make(
        key: "story.quadWreckDeath",
        category: .traffic,
        headlines: ["Teen Passenger Dies After ATV Hits Culvert at Dusk", "Driver Had Been Warned About Speed"],
        law: "misdDBV",
        threshold: 6,
        spec: "Unintentionally killed {V} while driving an off-road vehicle in violation of a safety statute, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a passenger, was thrown from an ATV that struck a culvert at dusk on {DATE} and died. {D}, the driver, was going over 40 mph without lights, a deputy estimated. {DL} says a dog ran across the path.",
        state: [E(.physical, 3, "ATV", "No headlight working; speed estimate over 40 mph.", .search), E(.statement, 2, "Deputy", "Skid marks of 80 feet before the culvert.")],
        defense: [E(.statement, 1, "Dog", "{DL} says a dog ran across the path.")],
        role: "Sheriff's deputy",
        exam: [.direct("Tell the jury how you came to the scene.", "\"A call came in at about 8:20 p.m. about an ATV crash near a drainage culvert off a gravel road. I arrived about ten minutes later.\""), .direct("What did you find at the scene of the ATV crash?", "\"The ATV had no working headlight, and there were long skid marks, about eighty feet, leading to a culvert.\""), .direct("What was your estimate of the speed?", "\"Over 40 miles an hour based on the skid length and the damage. It was dusk, and {V} was thrown from the vehicle.\""), .direct("What happened to {V}?", "\"{V} was a passenger and was thrown from the ATV when it struck the culvert. {V} died from the injuries.\""), .direct("What did you see when you arrived?", "\"An ATV on its side, no working headlight, and {V} on the ground about twenty feet from the culvert. {D} was kneeling next to {V}.\""), .direct("What did the roadway tell you about speed?", "\"Eighty feet of skid marks leading to the culvert, then about thirty feet where the ATV tumbled. I estimated the speed at over forty.\""), .cross("{D} says a dog ran across the path, doesn't {D.he}?", "\"Yes, but I found no dog and no tracks. A neighbor later said a dog was on the path an hour earlier.\""), .cross("Dusk makes it hard to see, doesn't it?", "\"It does. Dusk is a hard time for visibility, which is why working lights matter.\""), .cross("Could a driver brake that hard because of an animal?", "\"Yes. The skid marks show braking, and braking fits an obstacle in the path.\""), .cross("Did you see a dog or any tracks?", "\"No dog and no tracks. It was dusk and the ground was hard, so tracks might not have shown.\""), .cross("What was the light like when the crash happened?", "\"It was dusk, about eight o'clock. Lights were needed but it wasn't completely dark.\"")],
        theory: ("{D} drove too fast without lights and a passenger died.", "A dog on the path."),
        allocution: "\"I'll never forgive myself.\"",
        truths: ("The headlight bulb had been removed.", "A neighbor saw a dog on the path an hour earlier."),
        defendant: [.direct("Were you speeding on the ATV?", "\"No. I was not going fast. I was driving at a normal speed on a path I had ridden before.\""), .direct("Why did you brake?", "\"A dog ran across the path. I hit the brakes hard, and the ATV slid toward the culvert.\""), .direct("Did the headlight work?", "\"I believed it did. It worked earlier, and I did not notice it was out.\""), .direct("Describe the ride for the jury.", "\"We'd been riding the trails for about half an hour. I was driving and {V} was behind me, holding on.\""), .direct("What happened on the path?", "\"A dog ran across the path from the left. I hit the brakes hard and tried to turn, and we were thrown toward the culvert.\""), .direct("Did you try to help {V}?", "\"Yes. I got to {V} right away, checked for a pulse, and called for help on my phone. I stayed until the deputies came.\""), .cross("The deputy found no working headlight, didn't they?", "\"That is what the deputy says. I thought it was working, and I am not sure what happened to it.\""), .cross("Eighty feet of skid marks suggests a lot of speed, doesn't it?", "\"It suggests braking. I was braking hard because of the dog.\""), .cross("{V} died. Do you accept responsibility?", "\"I was driving, and I wish I could take it back.\""), .cross("The skid marks suggest high speed. How fast were you going?", "\"Not fast, maybe twenty-five. I braked hard because of the dog.\""), .cross("The headlight wasn't working. Why were you riding at dusk without a light?", "\"I thought it worked earlier. I didn't check it before we started, and I regret that.\"")],
        openings: ("{V}, a passenger on an ATV, was thrown from it and killed when it struck a culvert at dusk. The ATV had no working headlight, and a deputy estimated its speed at over 40 miles an hour.", "Weigh the defense proof, which will show that a dog ran across the path and that {D} braked as any driver would. The State cannot show {D} acted recklessly rather than responding to an emergency."),
        closings: ("No headlight, dusk, over 40 miles an hour, and eighty feet of skid marks to a culvert. {V} is dead, and the driver chose to ride that way.", "A dog on a path, a driver who braked hard, and a terrible accident. The State has not proved that {D} was driving with reckless disregard."),
        timeline: [(0, "7:30 p.m.: the ride starts."), (0, "8 p.m.: the ATV hits the culvert."), (0, "8:20 p.m.: deputies arrive.")],
        identified: "A deputy.",
        mood: .sympathetic)

    static let keyboardSabotage = SmallCases.make(
        key: "story.keyboardSabotage",
        category: .cyber,
        headlines: ["Fired IT Worker Wipes Company Files Remotely", "Server Logs Show Deletion From Home Address"],
        law: "damagingComputers",
        threshold: 6,
        spec: "Willfully damaged the computers of {V}, a company, by deleting its data without authority, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} was fired on {DATE}. That night, files on {V}'s server were deleted using {D}'s old credentials from {D}'s home address. Restoration cost $18,000. {DL} says a former coworker used {D.his} login.",
        state: [E(.digital, 3, "Server Logs", "Deletion from {D}'s home address at 9:40 p.m."), E(.document, 2, "Restoration Invoice", "$18,000 to restore the files.")],
        defense: [E(.statement, 1, "Coworker", "{DL} says a coworker used {D.his} login.")],
        role: "Company owner",
        exam: [.direct("Tell the jury about your company and how your server is set up.", "\"We're a design firm with about twenty employees. Our files are on an internal server, and each employee has a login that gives access based on role.\""), .direct("What happened to your server on the night of {DATE}?", "\"Files were deleted that night. The logs show the deletion came from {D}'s home address at 9:40 p.m., using {D.his} old credentials.\""), .direct("What was {DL}'s status at the company?", "\"{D.He} was fired that same day. I took the termination meeting myself. Access was supposed to be shut off, and it hadn't been yet.\""), .direct("What did it cost you to recover?", "\"$18,000 to restore the files. We hired outside specialists to rebuild what was lost, and we were without some of our data for days.\""), .direct("What happened on the night in question?", "\"At 9:40 p.m., hundreds of project files were deleted from the shared drive. The log shows it was done from {D.his} account at {D.his} home address.\""), .direct("Why was {D}'s account still active?", "\"I fired {D.him} that afternoon and told IT to shut off access, but it wasn't done until the next morning. I should have followed up.\""), .cross("Could someone else have used {DL}'s login?", "\"In theory, yes. The log shows the account, not the person. A coworker with the login could have used it.\""), .cross("Was the password known to anyone else?", "\"I can't say for certain. We had shared systems, and I don't know who else may have had access to the credentials.\""), .cross("Was {DL} angry when fired?", "\"Yes, {D.he} was upset. I wouldn't call it a threatening anger. {D.He} left without a scene and said little.\""), .cross("Has the defendant's password been shared with anyone?", "\"Possibly. Our IT department kept a wiki with shared passwords, and I know that was a weakness.\""), .cross("Did the log show the deletion came from the defendant's own computer?", "\"It showed the same IP address as {D.his} home, but not the device. Anyone on that network could have sent the commands.\"")],
        theory: ("{D} wiped a company server.", "A coworker's use of a login."),
        allocution: "\"I was angry. I'm sorry.\"",
        truths: ("{DL}'s home router logged the connection.", "{DL}'s password had been posted in the shared IT wiki for months."),
        defendant: [.direct("Did you delete files from {V}'s server?", "\"No. I never did. I was fired that day and I was upset, but I would never destroy a company's files.\""), .direct("Where were you at 9:40 that night?", "\"At home. I was home most of that evening, as I usually am. I wasn't doing anything with the company's server.\""), .direct("Who do you think used your login?", "\"A former coworker, I think. People knew my credentials, and I never changed the password. I can't prove who it was.\""), .direct("Describe what happened the day you were fired.", "\"I was called into the owner's office at about four and told my position was being eliminated. I packed my things and went home.\""), .direct("Where were you at 9:40 p.m.?", "\"At home, watching television and eating dinner. I didn't go online or touch my work computer.\""), .direct("What did you do with your login after you were fired?", "\"Nothing. I never changed the password, and it sat in the shared IT wiki for months. I did not sign in that night, and I did not delete anything.\""), .cross("The deletion came from your home address, didn't it?", "\"That's what the log says. I can't explain it. I didn't do it, but I realize how that looks.\""), .cross("You were fired that same day, weren't you?", "\"Yes. I was angry and hurt. I didn't take it out on the company, and I wouldn't have done something like this.\""), .cross("Your password was never changed, was it?", "\"No. I didn't think about it. I assumed the company would shut off my access, and it didn't happen in time.\""), .cross("The deletion came from your home address. How is that a coincidence?", "\"I live with a roommate, and others have used my Wi-Fi. I can't explain it, but I didn't do it.\""), .cross("You were fired that afternoon and angry. Isn't that a motive?", "\"I was hurt, not vindictive. I wanted to find another job, not destroy my old employer's work.\"")],
        openings: ("{D} was fired on {DATE}. That night, files on {V}'s server were deleted using {D}'s old credentials from {D}'s home address at 9:40, and restoring them cost $18,000. The State will show the logs and the invoice.", "The defense will present a login that others knew, a company that failed to cut off access, and no proof that {D} sat at the keyboard that night."),
        closings: ("Fired in the morning, files deleted that night, from {D}'s home, with {D}'s login. Eighteen thousand dollars later, the pattern is clear.", "A password isn't a person. Others knew the login, and the company never shut it off. The State has not proved {D} was the one who deleted anything."),
        timeline: [(0, "4 p.m.: {DL} is fired."), (0, "9:40 p.m.: the deletion."), (1, "9 a.m.: the owner finds the files gone.")],
        identified: "Server logs.",
        mood: .wantsConviction)

    static let hatchetDispute = SmallCases.make(
        key: "story.hatchetDispute",
        category: .violent,
        headlines: ["Neighbor Dispute Over Tree Ends With Fatal Wound on Driveway", "Autopsy Shows Single Wound"],
