        exam: [.direct("Tell us how you came to witness the confrontation.", "\"I live in the apartment next door. I heard shouting at the doorway and went to the window and started filming on my phone.\""), .direct("What did you see during the rent dispute?", "\"I saw {D} swing a baseball bat at {V}, the landlord, who was at the doorway. It happened quickly and I was filming.\""), .direct("What was {V}'s injury?", "\"A skull fracture. {V} needed surgery, and I saw the blood at the scene.\""), .direct("What was the argument about?", "\"Rent, and an entry by the landlord. They were already shouting when I started to record.\""), .direct("What did the landlord say and do just before the swing?", "\"{V} told {DL} that rent was three months overdue and that {V} was coming in to inspect. {V} put a hand on the door and stepped forward.\""), .direct("What did you see {D} do?", "\"{D.He} stepped back, grabbed a baseball bat from beside the door, and swung it at {V}'s head. {V} fell onto the landing.\""), .cross("{D} says {V} tried to enter without notice, doesn't {D.he}?", "\"That is what {DL} says. I thought a notice was posted, but I am not sure where.\""), .cross("Where was the bat before the swing?", "\"I think it was in the doorway. I did not see it picked up.\""), .cross("Did you see {V} step toward {D}?", "\"I saw {V} at the door. I did not see {V} swing or push.\""), .cross("Did you see a notice on the door?", "\"I saw a paper taped to a different door, I think the one next to it. I can't say whether it was for {D.him}.\""), .cross("Did {V} try to push inside?", "\"{V} put a hand on the door and took a step. I can't say whether that was an attempt to enter or just a reach.\"")],
        theory: ("{D} struck a landlord with a bat.", "A response to an entry."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} owed three months of rent.", "The notice was taped to the wrong door, so {DL} never saw the entry date."),
        defendant: [.direct("Did you swing the bat?", "\"Yes, I did. {V} tried to enter my home without notice, and I was afraid.\""), .direct("Why did you swing?", "\"I thought someone was coming in. It was reflex, and I did not think.\""), .direct("Had you received any notice of the entry?", "\"I did not see one. If it was posted, I missed it.\""), .direct("Describe your housing situation for the jury.", "\"I'd fallen behind on rent after my hours were cut. I owed about three months, and I'd told the landlord I'd have it soon.\""), .direct("What happened that afternoon?", "\"I heard someone at the door and saw it opening. I grabbed the bat that I keep by the door and swung before I saw who it was.\""), .direct("What did you do after?", "\"I dropped the bat, called 911, and tried to help {V}. I said I was sorry the whole time.\""), .cross("You owed three months of rent, didn't you?", "\"Yes. I know that does not help me, and I was behind.\""), .cross("A bat in the doorway. Why was it there?", "\"It was by the door for safety. I did not plan to use it.\""), .cross("{V} suffered a skull fracture. Aren't you responsible?", "\"I am responsible for the swing. I did not mean for it to go that far.\""), .cross("The landlord was knocking and announcing the entry. Why didn't you answer the door?", "\"I didn't hear a knock. I only heard the door opening, and I was scared.\""), .cross("A fractured skull is a serious injury. Do you accept responsibility?", "\"I do. I never meant to hurt anyone like that, and I think about it every day.\"")],
        openings: ("During a rent dispute, {D} struck {V}, a landlord, with a baseball bat, fracturing {V}'s skull and requiring surgery. A tenant filmed part of it.", "Listen for the defense evidence, which will show that {D} never received notice of an entry and swung out of fear that someone was forcing a way in."),
        closings: ("A baseball bat, a landlord at the door, a fractured skull, and a tenant's video. {D} owed three months' rent, and that is what this was about.", "{D} saw someone coming through the door without notice and swung in fear. The notice was taped to the wrong door, so {D} never knew."),
        timeline: [(-2, "A notice is taped to the door."), (0, "5 p.m.: the confrontation."), (0, "5:02 p.m.: the swing."), (0, "6 p.m.: deputies arrive.")],
        identified: "A tenant video.",
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mood: .divided,
        doctrines: ["selfDefense"])

    static let elderHomeNight = SmallCases.make(
        key: "story.elderHomeNight",
        category: .property,
        headlines: ["Resident, 84, Awakened by Intruder in Bedroom", "Fingerprints Found on Back Door Glass"],
        law: "burglary1",
        threshold: 8,
        spec: "Broke and entered the occupied dwelling of {V} at night with intent to commit larceny therein, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, 84, woke at 3 a.m. on {DATE} to find an intruder in her bedroom doorway. A jewelry box was taken. Fingerprints on the back door glass matched {D}. {DL} says {D.he} had done yard work there two weeks earlier.",
        state: [E(.forensic, 3, "Fingerprints", "{D}'s prints on the back door glass."), E(.statement, 3, "Victim", "{V} saw an intruder in the doorway.")],
        defense: [E(.statement, 1, "Yard Work", "{DL} says {D.he} did yard work there.")],
        role: "Victim",
        exam: [.direct("Please tell us about your home and who lives there.", "\"I'm 84 and live alone in the house where I raised my family. I've been there for fifty years.\""), .direct("What woke you at 3 a.m. on {DATE}?", "\"A noise in the house. I opened my eyes and saw someone standing in my bedroom doorway. I'm 84, and I was terrified.\""), .direct("What was taken?", "\"My jewelry box. When I got up the next morning, it was gone from the dresser. Some of what was in it belonged to my family.\""), .direct("What did the police find?", "\"Fingerprints on the glass of my back door that matched {D}. That was how they came to speak to {DL}.\""), .direct("What did you do when you saw the intruder?", "\"I screamed and the person ran down the hall. I heard the back door close and I called 911 from the bedroom phone.\""), .direct("How did the deputies find the person responsible?", "\"They dusted the back door glass and found fingerprints. A detective told me they matched {DL}, the person who mowed my lawn.\""), .cross("Could you see the intruder's face?", "\"No. It was dark, and I didn't have my glasses. I saw a shape in the doorway. I can't tell you whether it was {DL}.\""), .cross("Did {DL} ever work at your home?", "\"Yes, {D.he} did yard work for me about two weeks before. I didn't think of it at first. I've had several people do work.\""), .cross("Could {DL}'s prints be from the yard work?", "\"I suppose so. {D.He} may have touched the back door while working. I can't say how the prints got there.\""), .cross("Did you notice anything missing besides the jewelry box?", "\"A little cash in a drawer, I think. I'm not sure how much.\""), .cross("Did {D} ever come inside your home?", "\"Once, for a glass of water. {D.He} stayed in the kitchen and was always polite.\"")],
        theory: ("{D} broke into an elderly resident's home.", "A yard worker's prints."),
        allocution: "\"I'm sorry.\"",
        truths: ("The prints were on the inside of the broken pane.", "Pawn records show the jewelry was sold by someone with a different ID."),
        defendant: [.direct("Did you ever go to {V}'s home?", "\"Yes, I did yard work there about two weeks before the burglary. I was paid for it, and I got along with {V} fine.\""), .direct("Why were your prints on the back door glass?", "\"I must have touched it while I was working. I went in and out of the back for water and tools.\""), .direct("Did you break in that night?", "\"No. I was nowhere near that house. I would never hurt an elderly person or go into a home at night.\""), .direct("Describe the work you did for {V} in your own words.", "\"I mowed the lawn, trimmed the hedges, and cleaned out the gutters for two weekends. {V} was kind and paid me fairly.\""), .direct("How did your prints end up on the back door?", "\"I carried tools in and out and used the back door to get water. I must have touched the glass when I was resting.\""), .direct("Where were you the night of the burglary?", "\"At home, asleep. I live with my parents and I didn't leave the house.\""), .cross("Your fingerprints were on the back door glass, weren't they?", "\"Yes. That's what they say. I explained it. I worked there, and I touched that door.\""), .cross("You knew where the jewelry box was kept, didn't you?", "\"I had no idea. I never went inside beyond the kitchen. I didn't see any jewelry or ask about it.\""), .cross("Nobody can say where you were at 3 a.m., can they?", "\"No. I was home asleep. I live alone. I know it's not much, but it's the truth.\""), .cross("You knew where the house was and that {V} lived alone. Isn't that convenient?", "\"It was a quiet street and I knew {V} lived alone. I would never take advantage of someone I worked for.\""), .cross("You pawned jewelry that week, didn't you?", "\"No. I've never pawned anything in my life, and I don't know who did.\"")],
        openings: ("{V}, 84, woke at 3 a.m. to find an intruder in the bedroom doorway, and a jewelry box was taken. Fingerprints on the back door glass matched {D}. The State will show the prints and {V}'s account.", "The defense evidence includes a person who did yard work at that house two weeks earlier, touched the back door, and left prints in the most natural way. A print is not a burglary."),
        closings: ("An intruder in the doorway of an 84-year-old's bedroom, a missing jewelry box, and {D}'s prints on the back door glass. {D} had been there before and knew the layout.", "{D} worked there and touched that door. {V} never saw a face, and nobody saw {D} take anything. The State cannot say when those prints were left."),
        timeline: [(-14, "{DL} does yard work."), (0, "3 a.m.: the intruder."), (0, "3:20 a.m.: {V} calls 911."), (2, "A pawn ticket appears.")],
        identified: "Fingerprints.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I don't sleep in that bedroom now.",
        genders: ["V": .female])

    static let parkingOfficeSafe = SmallCases.make(
        key: "story.parkingOfficeSafe",
        category: .property,
        headlines: ["Parking Authority Office Broken Into, Safe Carried Out", "Dolly Tracks Lead to Loading Dock"],
        law: "feloniousBE",
        threshold: 6,
        spec: "Broke and entered a building of {V}, a parking authority, with intent to commit larceny therein, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A safe holding $8,400 in meter receipts was carried out of a parking authority office on {DATE}. Dolly tracks led to a loading dock, and a camera captured a pickup that belongs to {D}. {DL} says the pickup was lent to a cousin.",
        state: [E(.video, 3, "Dock Camera", "A pickup backs to the dock and a safe is loaded."), E(.document, 2, "Registration", "The pickup is registered to {D}.")],
        defense: [E(.statement, 1, "Cousin", "{DL} says a cousin borrowed the pickup.")],
        role: "Authority director",
        exam: [.direct("Tell us about your authority and what was in the safe.", "\"I direct a small parking authority that collects meter fees for the town. The safe held eight thousand four hundred dollars from the last two weeks of meter receipts.\""), .direct("What was taken from your office?", "\"A safe with $8,400 in meter receipts. It was carried out through the loading dock overnight.\""), .direct("Whose pickup is it?", "\"It is registered to {D}. Dolly tracks led from our office to the same dock.\""), .direct("How did you discover the theft?", "\"My assistant opened the office at seven and found the side door open and the safe gone. A dolly tracked wheel marks across the floor to the loading dock.\""), .direct("What did the dock camera show?", "\"At 1:30 a.m., a pickup backs up to the dock. Two people load the safe onto the tailgate using a dolly and drive away at 1:50.\""), .direct("What did you do after you saw the dock camera footage?", "\"I gave it to deputies and showed them the dolly tracks. I also checked who had keys to the office, and that list was short.\""), .cross("{D} says a cousin borrowed the pickup, doesn't {D.he}?", "\"That is what {D.he} says. I cannot name the cousin, and I do not know whether one exists.\""), .cross("The face is not visible on the camera, is it?", "\"No. It is dark and the person is turned away. I can tell you about the truck, not the driver.\""), .cross("Could someone have used the pickup without the defendant knowing?", "\"It is possible. I only know that the registration is {DL}'s.\""), .cross("Can you read the license plate on the video?", "\"Partly. A deputy enhanced it and traced it to {DL}'s pickup, but the video doesn't show either person's face.\""), .cross("Who has keys to the office?", "\"Four people, including me. The side door lock was picked or forced, and I can't say which.\"")],
        theory: ("{D} took a safe from an office.", "A cousin with the pickup."),
        allocution: "\"I'm sorry.\"",
        truths: ("Safe paint was on {DL}'s truck bed.", "The cousin's phone placed the cousin at the town dock the night of the theft."),
        defendant: [.direct("Did you take the safe?", "\"No. I did not take it, and I was not at the parking authority that night.\""), .direct("Who had your pickup?", "\"A cousin borrowed it for a couple of days. I lent it with the keys.\""), .direct("Tell us about your pickup.", "\"It's a gray work truck I use for hauling. I keep the keys on a hook by the door, and my cousin sometimes borrows it.\""), .direct("Who had the pickup the night of the theft?", "\"My cousin borrowed it for a couple of days to move some furniture. I wasn't home that night.\""), .direct("Why was there paint on your truck bed?", "\"I hauled a table that week and it left paint. The paint isn't the safe's paint, though it's similar in color.\""), .direct("What did you tell deputies when they asked about your pickup?", "\"That I had lent it to my cousin for the evening and that I was home. I gave them my cousin's name and the town where my cousin lives.\""), .cross("The cousin lives in another county, doesn't the cousin?", "\"Maybe. I am not sure. I lent the truck and did not track where it went.\""), .cross("Paint matching the safe is in your truck bed. How is that a coincidence?", "\"I cannot explain it. I hauled a table, and nothing more.\""), .cross("You can't give the cousin's full name or number?", "\"I can give a name. I don't have a current number because the cousin changed phones.\""), .cross("The pickup is yours and the paint is in your truck. Doesn't all of that point to you?", "\"It points to my truck. It doesn't point to me, because I wasn't driving it.\""), .cross("Paint matching the safe was in your truck bed, wasn't it?", "\"Yes. That is why I told deputies about my cousin right away. My cousin borrowed the pickup that night, and the paint came from the load.\"")],
        openings: ("A safe holding $8,400 in meter receipts was carried out of a parking authority office. A dock camera shows a pickup loading it, and that pickup is registered to {D}.", "Weigh the defense proof, which will show that {D} lent the pickup to a cousin and that no face was ever seen. Ownership of a truck does not prove who loaded the safe."),
        closings: ("Dolly tracks to a loading dock, a pickup backing up to it, safe paint on {D}'s truck bed, and a registration in {D}'s name. These facts add up.", "A camera that shows a truck but not a face, and a cousin who borrowed it. The State has proved who owns the pickup, not who drove it."),
        timeline: [(0, "1:30 a.m.: a pickup backs to the dock."), (0, "1:50 a.m.: the safe is loaded."), (0, "7 a.m.: staff find the office open.")],
        identified: "A dock camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let barBrokenBottle = SmallCases.make(
        key: "story.barBrokenBottle",
        category: .violent,
        headlines: ["Patron Slashed With Broken Bottle in Bar Fight", "Surgery Needed for Facial Cut"],
        law: "awdw",
        threshold: 6,
        spec: "Assaulted {V} with a deadly weapon, a broken bottle, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A fight at a bar on {DATE} ended with {V} slashed across the face by a broken bottle. {V} needed surgery. A bartender said {D} broke the bottle on the bar and swung. {DL} says {V} had a glass first.",
        state: [E(.statement, 3, "Bartender", "{D} broke a bottle and swung."), E(.forensic, 2, "Medical Records", "A facial cut requiring stitches and surgery.")],
        defense: [E(.statement, 1, "Glass First", "{DL} says {V} had a glass first.")],
        role: "Sheriff's deputy",
        exam: [.direct("Tell the jury how you came to respond to the bar.", "\"A 911 call came in at about 11:15 p.m. reporting a fight and an injured patron. I arrived within eight minutes and found {V} on a stool with a towel against the face.\""), .direct("What did you find at the bar on {DATE}?", "\"{V} had been slashed across the face with a broken bottle and was bleeding badly. The bar was in chaos, and people were pointing.\""), .direct("What did the bartender tell you?", "\"{D} broke a bottle on the bar and swung it. The bartender gave me that account at the scene and I wrote it down.\""), .direct("What were {V}'s injuries?", "\"A deep facial cut requiring stitches and surgery. The medical records show the extent. {V} will have a scar from it.\""), .direct("What was the scene like when you arrived?", "\"Glass on the floor near the bar, a broken bottle on the counter, and a crowd standing back. The bartender pointed me to {V} and told me who the bartender thought did it.\""), .direct("What did the bartender say {D} did?", "\"That {D.he} grabbed a bottle, broke it on the edge of the bar, and swung it at {V}'s face. The bartender said the whole thing took a few seconds.\""), .cross("{DL} says {V} had a glass first, doesn't {D.he}?", "\"I wasn't present when it started. I can only tell you what the bartender and others told me afterward.\""), .cross("Did anyone else tell you {V} came at the defendant?", "\"One person said there was pushing and some of it involved {V}. I can't say who did what first in the chaos.\""), .cross("Was {DL} still at the bar when you arrived?", "\"No. {DL} had left by then. I located {DL} later and spoke with {DL}.\""), .cross("Did the bartender say {V} had a glass in hand?", "\"Not in the first statement. Later the bartender said there might have been a glass and some shoving, but wasn't sure of the order.\""), .cross("Did you recover any surveillance video from the bar?", "\"The bar has a camera over the register, but it points at the cash drawer, not the dance floor, and it showed nothing useful.\"")],
        theory: ("{D} slashed a patron.", "A response to a glass."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} left through the back door.", "The bartender admitted seeing {V} lunge with a glass before the bottle broke."),
        defendant: [.direct("What happened at the bar that night?", "\"{V} and I got into an argument, and {V} came at me with a glass. I grabbed a bottle to defend myself.\""), .direct("Did you break the bottle on purpose?", "\"It broke when I hit the bar, trying to scare {V.him} off. I wasn't trying to cut anyone, and I didn't expect what happened.\""), .direct("Why did you leave the bar?", "\"I was scared and upset. I knew I'd done something bad. I shouldn't have left, but I panicked.\""), .direct("Tell the jury what you were doing at the bar that night.", "\"Having a few drinks with friends after work. I'd been there about two hours when {V} and I got into an argument about a spilled drink.\""), .direct("What did {V} do?", "\"{V} grabbed a glass off the bar and came at me. I backed up into the bar and picked up the nearest bottle to keep {V} away.\""), .direct("How did the bottle break?", "\"I hit it against the bar to warn {V}, and it shattered. I swung it in a panic and I didn't mean to hit {V.him}.\""), .cross("The bartender says you broke the bottle and swung, doesn't {D.he}?", "\"That's what the bartender says. It happened fast. I did swing, but I was defending myself.\""), .cross("{V} needed surgery for the cut, didn't {V.he}?", "\"Yes. I am truly sorry. I didn't mean for that to happen. It went much further than I wanted.\""), .cross("You left before deputies came, didn't you?", "\"Yes. I should have stayed. I was frightened. I came forward when I calmed down.\""), .cross("You broke a bottle on purpose and swung it. Isn't that an attack?", "\"It was a defense. I never meant to hurt anyone, but I can't say I didn't swing.\""), .cross("You left through the back door. Why not stay and talk to deputies?", "\"I was scared and I thought I'd be blamed. I know I should have stayed.\"")],
        openings: ("A fight at a bar ended with {V} slashed across the face by a broken bottle and needing surgery. The bartender says {D} broke the bottle on the bar and swung. The State will present the deputy and the medical records.", "Jurors will hear that {V} had a glass first, a quick fight in a crowded bar, and a bottle swung in fear. {D} was reacting to an attack, not starting one."),
        closings: ("A bottle broken on the bar and swung at {V}'s face. The bartender saw it, and the medical records prove what it did. {D} left before help came.", "A glass raised, a fight in seconds, and a defensive swing. {D} never meant to scar anyone. The State has not proved the swing was anything more than self-defense."),
        timeline: [(0, "11 p.m.: the argument."), (0, "11:10 p.m.: the bottle."), (0, "11:15 p.m.: {DL} leaves.")],
        identified: "A bartender.",
        aggravating: ["The defendant was armed with a deadly weapon at the time of the crime"],
        mood: .indifferent,
        doctrines: ["selfDefense"])

    static let dieselDrainage = SmallCases.make(
        key: "story.dieselDrainage",
        category: .property,
        headlines: ["Diesel Drained From Eight Trucks at Contractor's Yard", "Hose and Cans Found in Truck Bed"],
        law: "felonyLarceny",
        threshold: 6,
        spec: "Stole diesel fuel valued at $5,800 belonging to {V}, a contractor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Diesel worth $5,800 was drained from eight trucks over three nights ending {DATE}. A yard camera showed {D}'s truck and a siphon hose. Cans of diesel were in {D}'s truck bed. {DL} says the cans held fuel from {D.his} own tank.",
        state: [E(.video, 3, "Yard Camera", "{D}'s truck and a siphon hose at the tanks."), E(.physical, 3, "Fuel Cans", "Six cans of diesel in {D}'s truck bed.", .search)],
        defense: [E(.statement, 1, "Own Tank", "{DL} says the cans held fuel from {D.his} own tank.")],
        role: "Contractor",
        exam: [.direct("Please describe your yard and how you store diesel.", "\"I run a small excavation business with eight trucks. We keep two above-ground tanks in the yard, and I fill the trucks from them each morning.\""), .direct("What did you discover about your fuel on {DATE}?", "\"Diesel worth $5,800 had been drained from eight of my trucks over three nights. The tanks were low, and I knew I hadn't used it.\""), .direct("What does the yard camera show?", "\"{D}'s truck, parked near the tanks, and a siphon hose at the tanks. It shows the activity over the nights in question.\""), .direct("What was found in {DL}'s truck?", "\"Six cans of diesel in the truck bed. Deputies found them when they went to speak to {DL}.\""), .direct("How did you discover the missing fuel?", "\"Over three mornings, the tank gauges read lower than they should have. On the fourth I checked the stick and found eight trucks short by about two hundred gallons.\""), .direct("What does the yard camera record?", "\"A pickup backs up to the tanks at about two in the morning, someone runs a hose from the tank to cans in the bed, and the truck leaves. The same truck appears two nights earlier.\""), .cross("Can you tell the diesel in the cans was yours?", "\"No. Diesel is diesel. I can't say that fuel came from my trucks. I can say how much I lost and when.\""), .cross("{DL} says the cans held fuel from {D.his} own tank, doesn't {D.he}?", "\"I have no way to know. All I know is my trucks lost $5,800.\""), .cross("Did you see {DL} at your yard?", "\"Not in person. I saw {D.his} truck on the camera. I wasn't at the yard when the fuel was taken.\""), .cross("Can you see the driver's face on the video?", "\"No. The driver wears a hooded jacket and keeps the head down. I can see the truck and the hose.\""), .cross("Is the pickup in the video the same make and color as {D}'s?", "\"Yes, a dark crew-cab pickup. There are a lot of those in the county.\"")],
        theory: ("{D} stole diesel from a contractor's yard.", "Fuel from {D.his} own tank."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} drives only a gasoline pickup.", "The diesel in the cans matched the dye sold at the farm co-op where {DL} bought it."),
        defendant: [.direct("Where did the diesel in your truck bed come from?", "\"From my own tank. I fill cans from my truck's tank so I can fuel my equipment. It's what I do on my property.\""), .direct("Were you at {V}'s yard?", "\"I may have driven by. I know the yard. But I didn't siphon anything from any truck there.\""), .direct("What about the hose?", "\"I own a siphon hose. Plenty of people do. I use it to move fuel between my own tanks, not to take someone else's.\""), .direct("Walk us through what you do and what you drive.", "\"I run a small hauling business and I drive a diesel pickup. I fill my tank at a farm co-op near my house.\""), .direct("Where did the diesel in the cans come from?", "\"From my tank. I keep cans in the truck bed for my generators and a skid steer at job sites.\""), .direct("Were you near the contractor's yard that week?", "\"I may have driven past it. It's on a road I take to the co-op, but I didn't stop or touch anything.\""), .cross("The camera shows your truck and a hose at the tanks, doesn't it?", "\"It shows a truck like mine. I can't say it's mine. I know how it looks, but I didn't do it.\""), .cross("Six cans is a lot of fuel, isn't it?", "\"It's a lot, but I go through fuel. I keep cans full so I don't run out in the middle of a job.\""), .cross("$5,800 of diesel went missing from eight trucks, correct?", "\"That's what {V} says. I feel for {V}. I wasn't the one who took it.\""), .cross("Six cans is a lot of fuel. Why so much?", "\"I use that much when I'm working at remote sites. I fill the cans once a week.\""), .cross("A siphon hose was at the tanks and you own one. Isn't that a coincidence?", "\"It's a common tool. I use mine to move fuel between my own tanks.\"")],
        openings: ("Diesel worth $5,800 was drained from eight trucks over three nights. A yard camera shows {D}'s truck and a siphon hose at the tanks, and six cans of diesel were in {D}'s truck bed. The State will show the video and the cans.", "Jurors will also see a person who fills cans from {D.his} own tank, a truck that looks like many others, and no proof that any fuel in those cans came from {V}."),
        closings: ("Eight trucks drained, a siphon hose on camera, {D}'s truck at the tanks, and six cans of diesel in the bed. The pieces fit.", "Diesel is diesel. The State cannot show that the cans held {V}'s fuel, and the camera does not show {D}'s face. A truck that looks like {D}'s is not enough."),
        timeline: [(-2, "The first night."), (0, "2 a.m.: {DL}'s truck at the yard."), (0, "7 a.m.: the contractor finds dry tanks.")],
        identified: "A yard camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction)

    static let lotInvestmentFraud = SmallCases.make(
