        spec: "Obtained over $100,000 from {V}, an investor, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sold {V} shares in three lots of land for $140,000 on {DATE}. County deeds showed the lots belonged to other people. {DL} says {D.he} was negotiating to buy them and the sales fell through.",
        state: [E(.document, 3, "Deeds", "The three lots belong to other owners."), E(.document, 3, "Sales Contract", "A $140,000 contract signed by {D}.")],
